# coding: utf-8
from lesson_authoring import entry as E
B=[['拉丁 pater／patris','父亲']]
W=[
E('paternal','英 /pəˈtɜːnəl/；美 /pəˈtɜːrnəl/','父亲的；父方的；像父亲般的','把关系或感觉定位在父亲这一边。','经法语 paternal 接拉丁 paternalis／paternus，来自 pater“父亲”；现代不是 pattern 的形容词。',B+[['拉丁 paternus／paternalis → 法语 paternal','父亲的、父方的'],['英语 paternal','父亲或父系相关的；父亲般的']],'paternal grandparents 是父亲的父母，即祖父母；paternal affection 是父亲的关爱，也可以描述像父亲一样的关怀。它说明关系或风格，不自动表示专断控制，那是 paternalistic 常涉及的另一层。','paternal grandparents；paternal affection；a paternal figure。','maternal 是母亲或母方的，parental 同时泛指父母；paternal 只落在父亲这一边。',('Her paternal grandparents live nearby.','她的祖父母住在附近。'),('He spoke with a kind of paternal affection.','他说话时带着一种父亲般的关爱。'),sources=['https://en.wiktionary.org/wiki/paternal','https://www.etymonline.com/word/paternal']),
E('paternity','英 /pəˈtɜːnəti/；美 /pəˈtɜːrnəti/','父亲身份；父子女关系','问的不是他是不是一个男人，而是他是不是某个孩子的父亲。','经法语 paternité 接拉丁 paternitas，来自 paternus“父亲的”；是历史名词支线，不只把英语 paternal 改尾巴。',B+[['拉丁 paternus → paternitas','父亲的 → 父亲身份'],['法语 paternité → 英语 paternity','父亲身份、父子女关系']],'paternity test 是亲子鉴定中的父亲身份检测，paternity leave 是与成为父亲有关的休假。paternity 强调身份或关系，不是形容一个人性格是否有父爱；后者可能用 paternal 描述。','paternity leave；a paternity test；establish paternity。','fatherhood 可以宽泛谈当父亲的生活体验，paternity 在制度、身份和检测相关搭配中更常见。',('He took paternity leave after his daughter was born.','女儿出生后，他休了陪产育儿假。'),('The story centres on a dispute over paternity.','故事围绕一场父亲身份争议展开。'),sources=['https://en.wiktionary.org/wiki/paternity']),
E('paternalism','英 /pəˈtɜːnəlɪzəm/；美 /pəˈtɜːrnəlɪzəm/','家长主义','以“我是为你好”为理由，替别人决定他该怎么做。','paternal“父亲般的”+ -ism，表示一种做法或观念；把父亲式权威比喻到机构、政府和管理关系。',B+[['英语 paternal + -ism → paternalism','父亲式处理方式 → 以照顾为理由的代决策或限制']],'paternalism 的重点不只是提供帮助，而是自认为更懂对方利益，从而替对方作主、限制选择。讨论它时，人们常争论保护与自主之间的界限；这个词不要求作决定的人真是父亲或男性。','paternalism in management；a form of paternalism；criticism of paternalism。','care 是照顾，paternalism 多涉及替别人决定。提供选项与支持，和直接取消对方选择权，是不同做法。',('The policy was criticised as a form of paternalism.','这项政策被批评为一种家长主义。'),('She wanted support without the paternalism of having every decision made for her.','她希望获得支持，而不想接受别人替她作出所有决定的家长式安排。'),sources=['https://en.wiktionary.org/wiki/paternalism']),
E('paternalistic','英 /pəˌtɜːnəˈlɪstɪk/；美 /pəˌtɜːrnəˈlɪstɪk/','家长式的、以保护为由替人作主的','摆出“我知道什么对你最好”的管理姿态。','paternalist／paternalism 一族加形容词成分 -ic，表示具有家长主义特征。',B+[['英语 paternal → paternalism／paternalist','父亲式态度 → 家长主义'],['英语 paternalistic','具有这种替人作主倾向的']],'a paternalistic employer 可能照顾员工很多，同时觉得员工应该接受他的安排。这个词指出权力与自主的关系，不是单纯夸老板和蔼；具体措施是否适当仍需结合场景判断。','a paternalistic attitude；paternalistic management；a paternalistic approach。','paternal 可以只是父亲般关爱；paternalistic 往往增加“替别人决定”的意味。patronizing 则更突出交流中的优越姿态。',('The company moved away from a paternalistic style of management.','公司逐渐摆脱了家长式管理风格。'),('Her advice was intended to help, but it sounded paternalistic.','她的建议本意是帮忙，听起来却像在替别人作主。'),sources=['https://en.wiktionary.org/wiki/paternalistic']),
E('patrician','/pəˈtrɪʃən/','古罗马贵族；贵族般的、上流社会的','先是特定的贵族身份，后来也用来描写上流阶层的气质。','来自拉丁 patricius，联系 patres“父辈、元老”的称呼，经法语 patricien 等形式进入英语。',B+[['拉丁 patres → patricius','父辈、元老 → 贵族阶层相关的'],['法语 patricien／英语 patrician','古罗马贵族；上流社会人物或风格']],'古罗马史中的 patricians 是有特定社会身份的贵族阶层，不能把所有有钱人都自动算进去。a patrician manner 在现代叙述里可以说举止带贵族气质，可能是赞赏，也可能暗示高高在上。','a patrician family；Roman patricians；a patrician manner。','aristocrat 是更通用的贵族，patrician 在古罗马语境有具体历史含义；形容气质时则不一定在证明真实血统。',('The book describes the influence of patrician families in Rome.','这本书描述了罗马贵族家族的影响。'),('He spoke with a calm, patrician confidence.','他说话时带着一种沉着的贵族式自信。'),sources=['https://en.wiktionary.org/wiki/patrician','https://www.etymonline.com/word/patrician']),
E('patrimony','英 /ˈpætrɪməni/；美 /ˈpætrɪmoʊni/','祖传财产；文化遗产〔正式〕','父辈留下的东西，后来扩展到一个社会从前人那里继承的财富。','经法语 patrimoine／patremoine 接拉丁 patrimonium，来自 pater 与表示状态或关系的 -monium。',B+[['拉丁 patrimonium → 法语 patrimoine','从父辈继承的财产'],['英语 patrimony','祖产；共同文化遗产']],'a family’s patrimony 可以是祖传土地或财物，cultural patrimony 则是建筑、艺术、文献等共同继承的文化财富。这个词不只是数字意义的遗产金额，也能强调代际传承与保护责任。','cultural patrimony；a national patrimony；preserve patrimony。','inheritance 更通用，可指具体继承物；patrimony 更正式，也常突出父辈或共同文化的传承。',('The old house formed part of the family’s patrimony.','这座老宅是这个家族祖产的一部分。'),('The museum helps preserve the region’s cultural patrimony.','博物馆帮助保存这个地区的文化遗产。'),sources=['https://en.wiktionary.org/wiki/patrimony','https://www.etymonline.com/word/patrimony']),
E('patricide','/ˈpætrɪsaɪd/','弑父；弑父者〔正式、文学〕','把父亲作为受害对象的杀害行为。','patri- 取拉丁 pater 的词干，加 -cide“杀害、杀害者”；后半源自拉丁 caedere“杀”。',[['拉丁 pater／patris“父亲” + caedere“杀”相关词干','两个成分组合'],['英语 patricide','弑父行为；也可指实施者']],'在戏剧、神话或历史评论中，patricide 可能指弑父情节；a patricide 也可以指弑父者。它是正式且具体的词，普通家庭争吵或反抗父辈不应直接按字面称为 patricide，除非作者明确作比喻。','an act of patricide；a story of patricide；patricide in tragedy。','matricide 是弑母，homicide 是杀人这一更宽的概念；-cide 既可能指行为，也可能指行为者，需看句法。',('The tragedy revolves around an act of patricide.','这部悲剧围绕一起弑父事件展开。'),('The essay examines the theme of patricide in ancient stories.','这篇文章分析了古代故事中的弑父主题。'),sources=['https://en.wiktionary.org/wiki/patricide','https://www.etymonline.com/word/patricide']),
E('patter','英 /ˈpætə/；美 /ˈpætər/','连续轻响；快而流利的话语、套话','一条路是雨点细密敲打，另一条路是嘴里一串接一串地说。','轻响义是 pat“轻拍”的反复形式；快语义联系中古英语 pateren“急速念祷文”，来自拉丁 Pater noster“我们的父”祷文开头。两条来源不能全归 pater。',[['快语支线：拉丁 Pater noster → 中古英语 pateren','祷文开头 → 低声快速念祷文'],['英语 patter〔快语〕','流利急速的话；推销或表演套话'],['另源：pat“轻拍” → patter〔轻响〕','反复轻拍 → 连续的细小敲击声']],'the patter of rain 是雨点的轻响，sales patter 是推销员熟练的一套说辞。它们听起来都密密麻麻，很容易联想在一起，但词源分析要保留区别。说话义可以中性描写熟练，也可以暗示花言巧语。','the patter of rain；sales patter；a comedian’s patter。','pattern 是图案或模式，patter 是轻响或快语。两者拼写接近，不能把所有 patter 都当作 pattern 的缩写。',('We listened to the gentle patter of rain on the roof.','我们听着雨点轻轻敲打屋顶的声音。'),('The salesman began his familiar sales patter.','推销员开始了他那套熟练的推销说辞。'),sources=['https://www.etymonline.com/word/patter','https://en.wiktionary.org/wiki/patter'])]
